import { ColumnDef, Row } from '@tanstack/react-table';
import { AllowancesList } from '../../types/configs.types';
import TrashIcon from '@/components/icons/TrashIcon';
import EditIcon from '@/components/icons/EditIcon';
import { toast } from 'sonner';
import { apiDelete } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';

const ActionsCell = ({ row, onEdit }: { row: Row<AllowancesList>; onEdit: (row: AllowancesList) => void }) => {
    const refresh = row.original.refreshTable;

    const handleDelete = async () => {
        try {
            await apiDelete({ endpoint: endpoints.allowance.delete + row.original.id });
            toast.success('تم حذف البدل');
            refresh?.();
        } catch {
            toast.error('تعذر حذف البدل');
        }
    };

    return (
        <div className="me-6 text-end flex flex-row items-center justify-end gap-6">
            <button
                type="button"
                onClick={() => onEdit(row.original)}
                className="hover:bg-white-blue-300 rounded-full p-1"
                aria-label="تعديل"
            >
                <EditIcon className="text-primery-blue-400" />
            </button>
            <button type="button" onClick={handleDelete} className="hover:bg-white-blue-300 rounded-full p-1" aria-label="حذف">
                <TrashIcon className="text-[#E81E1E] cursor-pointer" />
            </button>
        </div>
    );
};

export const columns = (onEdit: (row: AllowancesList) => void): ColumnDef<AllowancesList>[] => [
    {
        id: 'employee_name',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الموظف
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-900 leading-[26.24px] font-medium tracking-normal">
                {row.original.employee_name || row.original.employee?.name || '—'}
            </div>
        ),
    },
    {
        accessorKey: 'name',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                اسم البند
            </div>
        ),
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.name}</p>
            </div>
        ),
    },
    {
        accessorKey: 'note',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                وصف
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {row.original.note ?? '—'}
            </div>
        ),
    },
    {
        accessorKey: 'basic_salary',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                المبلغ
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {row.original.basic_salary}
            </div>
        ),
    },
    {
        accessorKey: 'date',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                تاريخ البند
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] tabular-nums">
                {row.original.date}
            </div>
        ),
    },
    {
        id: 'actions',
        header: () => (
            <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الاجراءات
            </div>
        ),
        cell: ({ row }) => <ActionsCell row={row} onEdit={onEdit} />,
    },
];
