import UnderlineHeading from '@/components/heading/UnderlineHeading';
import Deductions from './Deductions.page';
import { cn } from '@/lib/utils';
import { useState } from 'react';
import Allowances from './Allowances.page';
import { useSearchParams } from 'react-router-dom';

type ShiftsTab = 'payroll' | 'deductions';

const PayrollAndAllowances = () => {
    const [searchParams, setSearchParams] = useSearchParams();
    const payrollParam = searchParams.get('payroll');

    const activeTab: ShiftsTab = payrollParam
        ? 'payroll'
        : searchParams.get('tab') === 'deductions'
          ? 'deductions'
          : 'payroll';

    const handleSelect = (value: ShiftsTab) => {
        setSearchParams(
            (prev) => {
                const next = new URLSearchParams(prev);
                if (value === 'deductions') {
                    next.set('tab', 'deductions');
                    next.delete('payroll');
                } else {
                    next.delete('tab');
                }
                return next;
            },
            { replace: true },
        );
    };

    return (
        <div className="w-full mt-6 mb-20">
            <UnderlineHeading text="الخصومات و البدلات" className="" />
            <div className="w-full flex flex-row items-center gap-[1px] my-6">
                <button
                    type="button"
                    onClick={() => handleSelect('deductions')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-s-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'deductions',
                            'bg-primery-blue-400': activeTab !== 'deductions',
                        },
                    )}
                >
                    الخصومات
                </button>
                <button
                    type="button"
                    onClick={() => handleSelect('payroll')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-e-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'payroll',
                            'bg-primery-blue-400': activeTab !== 'payroll',
                        },
                    )}
                >
                    البدلات
                </button>
            </div>

            {activeTab === 'deductions' && (
                <>
                    <Deductions />
                </>
            )}
            {activeTab === 'payroll' && <Allowances />}
        </div>
    );
};

export default PayrollAndAllowances;
