import StatisticsCards from '@/components/cards/StatisticsCards';
import GroupIcon from '@/components/icons/user/GroupIcon';
import MinusUserIcon from '@/components/icons/user/MinusUserIcon';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { allowanceDashboardStats } from '@/features/humanResources/types/employeesStats.types';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useCallback, useEffect, useState } from 'react';
import AllowancesList from '../components/allowancesList/AllowancesList';

const Allowances = () => {
    const now = new Date();
    const [month, setMonth] = useState(now.getMonth() + 1);
    const [year, setYear] = useState(now.getFullYear());
    const [stats, setStats] = useState<allowanceDashboardStats | null>(null);

    const fetchDashboard = useCallback(async () => {
        try {
            const res = await apiGet({
                endpoint: endpoints.allowance.dashboard,
                queryParams: { month, year },
            });
            setStats(res.data.data);
        } catch {
            setStats(null);
        }
    }, [month, year]);

    useEffect(() => {
        fetchDashboard();
    }, [fetchDashboard]);

    const cards: Card[] = [
        { text: 'إجمالي الرواتب', num: stats?.total_allowances, percent: 12, icon: <GroupIcon /> },
        { text: 'الحوافز و البدلات', num: stats?.total_allowances, percent: 0, icon: <UserRemoveIcon />, label: 'ريال' },
        { text: 'الخصومات', num: stats?.total_deductions, percent: -0.3, icon: <TwoUsersIcon />, label: 'ريال' },
        { text: 'صافي الراتب', num: stats?.total_net_salary, percent: -0.3, icon: <MinusUserIcon />, label: 'ريال' },
    ];

    return (
        <div className="w-full mt-6 mb-20">
            <StatisticsCards cards={cards} className="mt-6" />
            <AllowancesList
                month={month}
                year={year}
                onMonthYearChange={(m, y) => {
                    setMonth(m);
                    setYear(y);
                }}
                onDashboardRefresh={fetchDashboard}
            />
        </div>
    );
};

export default Allowances;
