import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar as AllowancesToolbar, type AllowancesDataTableToolbarProps } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { TableCell, TableRow } from '@/components/ui/table';
import { AllowancesList as AllowancesListRow } from '../../types/configs.types';
import type { AllowanceEditDraft } from '../../types/allowanceEdit.types';
import AddAllowance from '@/features/humanResources/components/popups/AddAllowance';

type ToolbarPassThrough = Omit<
    AllowancesDataTableToolbarProps,
    'month' | 'year' | 'onMonthYearChange' | 'onAddAllowance'
>;

interface AllowancesListProps {
    month: number;
    year: number;
    onMonthYearChange: (month: number, year: number) => void;
    onDashboardRefresh: () => void | Promise<void>;
}

export default function AllowancesList({ month, year, onMonthYearChange, onDashboardRefresh }: AllowancesListProps) {
    const [data, setData] = useState<AllowancesListRow[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingAllowance, setEditingAllowance] = useState<AllowanceEditDraft | null>(null);
    const lastFetchOptionsRef = useRef<FetchDataOptions | null>(null);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            lastFetchOptionsRef.current = options;
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.allowance.list,
                    queryParams: {
                        page: options.pageIndex + 1,
                        pageSize: options.pageSize,
                        month,
                        year,
                        ...options.filters,
                        search: options.globalFilter,
                    },
                });

                setData(response.data.data.data);
                const perPage = response.data.data.pagination.per_page || options.pageSize;
                setPageCount(Math.ceil(response.data.data.pagination.total / perPage));
                setTotalCount(response.data.data.pagination.total);
            } catch (error) {
                console.error('Error fetching data:', error);
            } finally {
                setIsLoading(false);
            }
        },
        [month, year],
    );

    useEffect(() => {
        const opts = lastFetchOptionsRef.current;
        if (opts) {
            fetchData(opts);
        }
    }, [month, year, fetchData]);

    const refetchFromLastOptions = useCallback(async () => {
        const opts =
            lastFetchOptionsRef.current ??
            ({
                pageIndex: 0,
                pageSize: 10,
                sorting: [],
                filters: {},
                globalFilter: '',
            } as FetchDataOptions);
        await fetchData(opts);
        await onDashboardRefresh?.();
    }, [fetchData, onDashboardRefresh]);

    const handleEdit = useCallback((row: AllowancesListRow) => {
        setEditingAllowance({
            id: row.id,
            employee_id: row.employee_id,
            name: row.name,
            amount: row.amount,
            note: row.note ?? null,
            date: row.date,
            currency: 'sar',
        });
        setDialogOpen(true);
    }, []);

    const Toolbar = useCallback(
        (props: ToolbarPassThrough) => (
            <AllowancesToolbar
                {...props}
                month={month}
                year={year}
                onMonthYearChange={onMonthYearChange}
                onAddAllowance={() => {
                    setEditingAllowance(null);
                    setDialogOpen(true);
                }}
            />
        ),
        [month, year, onMonthYearChange],
    );

    const totalAllowanceOnPage = useMemo(() => {
        return data?.reduce((sum, row) => {
            const n = Number(row.basic_salary);
            return sum + (Number.isFinite(n) ? n : 0);
        }, 0);
    }, [data]);

    const tableFooter = (
        <TableRow className="border-t-2 border-[#E8E7EA] bg-white-blue-50/90 hover:bg-white-blue-50/90 font-cairo">
            <TableCell colSpan={3} className="p-4" />
            <TableCell className="p-4 text-end text-sm font-semibold text-primery-blue-700 align-middle">
                إجمالي البدلات
            </TableCell>
            <TableCell className="p-4 text-sm font-semibold text-primery-blue-900 tabular-nums align-middle">
                {totalAllowanceOnPage?.toLocaleString('ar-SA', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                })}
            </TableCell>
            <TableCell colSpan={2} className="p-4" />
        </TableRow>
    );

    return (
        <>
            <div className="mt-6 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                <DataTable
                    columns={columns(handleEdit)}
                    data={data}
                    pageCount={pageCount}
                    totalCount={totalCount}
                    onFetchData={fetchData}
                    DataTableToolbar={Toolbar}
                    isLoading={isLoading}
                    tableFooter={tableFooter}
                />
            </div>
            <AddAllowance
                open={dialogOpen}
                setAddAllowance={(open) => {
                    setDialogOpen(open);
                    if (!open) {
                        setEditingAllowance(null);
                    }
                }}
                onCreated={refetchFromLastOptions}
                editingAllowance={editingAllowance}
            />
        </>
    );
}
