import { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Filters } from '@/types/table.types';
import { Employee } from '@/types/employee.types';
import ExportToPDF from './ExportToPDF';

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => ({
    label: String(i + 1),
    value: String(i + 1),
}));

function buildYearOptions(centerYear: number) {
    const years: { label: string; value: string }[] = [];
    for (let y = centerYear - 5; y <= centerYear + 5; y++) {
        years.push({ label: String(y), value: String(y) });
    }
    return years;
}

export interface AllowancesDataTableToolbarProps {
    table: Table<Employee>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    data: unknown[];
    handleRefreshTable?: () => void;
    month: number;
    year: number;
    onMonthYearChange: (month: number, year: number) => void;
    onAddAllowance: () => void;
}

export function DataTableToolbar({
    globalFilter,
    setGlobalFilter,
    filters,
    setFilters,
    data,
    month,
    year,
    onMonthYearChange,
    onAddAllowance,
}: AllowancesDataTableToolbarProps) {
    const yearOptions = buildYearOptions(year);

    return (
        <>
            <div className="flex flex-col p-2 gap-3 sm:flex-row sm:items-center sm:justify-between">
                <UnderlineHeading text="تفاصيل البدلات" />
                <div className="flex w-full flex-wrap items-center gap-3 sm:justify-end">
                    <div className="flex flex-wrap items-center gap-2">
                        <span className="text-sm text-primery-blue-700 whitespace-nowrap">الفترة:</span>
                        <CustomSelect
                            value={String(month)}
                            onValueChange={(v) => onMonthYearChange(Number(v), year)}
                            placeholder="الشهر"
                            width="min-w-[88px]"
                            options={MONTH_OPTIONS}
                        />
                        <CustomSelect
                            value={String(year)}
                            onValueChange={(v) => onMonthYearChange(month, Number(v))}
                            placeholder="السنة"
                            width="min-w-[100px]"
                            options={yearOptions}
                        />
                    </div>
                    <div className="flex w-full sm:w-[287px] flex-row items-center border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                        <Input
                            placeholder="بحث"
                            value={globalFilter}
                            onChange={(event) => setGlobalFilter(event.target.value)}
                            className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                        />
                        <button type="button" className="bg-transparent border-none">
                            <SearchIcon className="text-white-blue-800" />
                        </button>
                    </div>
                    <div className="flex flex-row items-center gap-4">
                        <CustomSelect
                            value={(filters?.status as string) || ''}
                            onValueChange={(value) => {
                                setFilters({ ...filters, status: value });
                            }}
                            placeholder="فلتر"
                            width="min-w-[77px]"
                            options={[
                                { label: 'فلتر', value: '' },
                                { label: 'متاح', value: 'active' },
                                { label: 'غير متاح', value: 'not active' },
                            ]}
                        />
                    </div>
                    <div>
                        <PrimaryButton
                            type="button"
                            onClick={onAddAllowance}
                            className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                        >
                            <AddIcon />
                            <p className="text-xs tracking-normal font-normal leading-[22.49px]">إضافة بدل</p>
                        </PrimaryButton>
                    </div>

                    <ExportToPDF data={data} />
                </div>
            </div>
        </>
    );
}
